#!/usr/bin/env python3
"""
KEYHAVEN redesign - single-file installer (35 files embedded).

Usage:   python3 install_keyhaven.py "C:/path/to/Copy Store - Copy"
(the folder that contains package.json and src/)

Overwrites the listed files; a .bak copy of each replaced file is saved first.
Then run:  npx drizzle-kit push   and   npm run dev
"""
import base64, os, shutil, sys, zlib

FILES = {
"drizzle/0001_homepage_theme_newsletter.sql": "",
"src/app/admin/catalog/page.tsx": "",
"src/app/admin/homepage/page.tsx": "",
"src/app/admin/layout.tsx": "",
"src/app/admin/site/page.tsx": "",
"src/app/api/admin/[resource]/[id]/route.ts": "",
"src/app/api/admin/[resource]/route.ts": "",
"src/app/api/admin/categories/reorder/route.ts": "",
"src/app/api/admin/newsletter/route.ts": "",
"src/app/api/admin/site/[key]/route.ts": "",
"src/app/api/categories/route.ts": "eNpVj1sKwjAQRf+7isGvBDRdgAgiiBtwA2k66mCbaSep9YF7NxXU+Hvv4T6o7VgiPMAGNwfs4QkH4RZmtdD93uCCpZ0tC/pgdfUl1mVd5ZazEY8shOEPKYM7YWtzks8Z0VBV2o6SX+D1Ddhw8w4Og3eR2MNuu1caHgWAYx8iCI8BVmBHSzHtMQEbdFFpMyWq3wptxhMKKuwz0dgUesE5RBlQa8NSo2xuKt3PqY4DTeVaL1OvYBzEp9lq6k7Ss3gBlBlqTA==",
"src/app/api/newsletter/route.ts": "",
"src/app/globals.css": "",
"src/app/layout.tsx": "",
"src/app/page.tsx": "",
"src/components/NewsletterForm.tsx": "",
"src/components/ProductCard.tsx": "",
"src/components/RatingStars.tsx": "",
"src/components/admin/CatalogClient.tsx": "",
"src/components/admin/HomepageAdminClient.tsx": "",
"src/components/admin/SiteSettingsClient.tsx": "",
"src/components/admin/SortableList.tsx": "",
"src/components/home/AdSlot.tsx": "",
"src/components/home/HomeSections.tsx": "",
"src/components/site/Footer.tsx": "",
"src/components/site/FooterNewsletter.tsx": "",
"src/components/site/Header.tsx": "",
"src/components/site/PromoBanner.tsx": "",
"src/components/site/ThemeSync.tsx": "",
"src/db/schema.ts": "",
"src/lib/category-icons.ts": "",
"src/lib/commerce.ts": "",
"src/lib/site-config.ts": "",
"src/lib/site-data.ts": "",
"src/lib/theme.ts": ""
}

def main():
    if len(sys.argv) != 2:
        sys.exit('Usage: python3 install_keyhaven.py "<project root>"')
    root = sys.argv[1]
    if not os.path.isfile(os.path.join(root, "package.json")):
        sys.exit("No package.json in that folder - pass the project root (the one containing src/).")
    for rel, data in FILES.items():
        dst = os.path.join(root, *rel.split("/"))
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        if os.path.exists(dst):
            shutil.copy2(dst, dst + ".bak")
        with open(dst, "wb") as f:
            f.write(zlib.decompress(base64.b64decode(data)))
        print("placed", rel)
    print("\nDone: %d files. Next: npx drizzle-kit push   then   npm run dev" % len(FILES))

main()
